<?php declare(strict_types=1); namespace App\Domains\Odontogram\Controllers;
use App\Domains\Odontogram\Services\OdontogramService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Routing\Controller;
final class OdontogramController extends Controller { public function __construct(private OdontogramService $svc) {} public function index(): JsonResponse { return response()->json($this->svc->paginate(['organization_id'=>auth()->user()->organization_id,...request()->only(['patient_id','per_page','page'])])); } public function show(string $id): JsonResponse { return response()->json($this->svc->findById($id,auth()->user()->organization_id)); } public function store(Request $r): JsonResponse { return response()->json($this->svc->create($r->validate(['organization_id'=>'required|uuid','patient_id'=>'required|uuid|exists:patients,id','tooth_number'=>'required|string|max:5','tooth_type'=>'nullable|string','surface'=>'nullable|string','condition'=>'nullable|string','notes'=>'nullable|string','findings'=>'nullable|array'])),201); } public function update(string $id, Request $r): JsonResponse { return response()->json($this->svc->update($id,$r->validate(['tooth_type'=>'sometimes|string','surface'=>'sometimes|string','condition'=>'sometimes|string','notes'=>'nullable|string','findings'=>'nullable|array']),auth()->user()->organization_id)); } public function destroy(string $id): JsonResponse { $this->svc->delete($id,auth()->user()->organization_id); return response()->json(['success'=>true,'message'=>'Deleted.']); } }